-- =============================================================================
-- NONGKI CLOUD DATABASE - MASTER SETUP & FULL SEED
-- =============================================================================

-- 1. PLACES TABLE
CREATE TABLE IF NOT EXISTS public.places (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    category TEXT NOT NULL DEFAULT 'Kafe',
    description TEXT,
    address TEXT,
    image_url TEXT,
    image_urls TEXT[] DEFAULT '{}',
    rating NUMERIC(2,1) DEFAULT 4.5,
    review_count INT DEFAULT 50,
    price_min INT NOT NULL DEFAULT 10000,
    price_max INT NOT NULL DEFAULT 35000,
    opening_hours TEXT DEFAULT '09:00 - 22:00 WIB',
    is_open BOOLEAN DEFAULT TRUE,
    facilities TEXT[] DEFAULT ARRAY['Wi-Fi', 'Stopkontak', 'Area AC', 'Parkir'],
    latitude DOUBLE PRECISION,
    longitude DOUBLE PRECISION,
    accepts_order BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

ALTER TABLE public.places ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Public places select" ON public.places;
CREATE POLICY "Public places select" ON public.places FOR SELECT TO PUBLIC USING (true);
DROP POLICY IF EXISTS "Public places insert" ON public.places;
CREATE POLICY "Public places insert" ON public.places FOR ALL TO PUBLIC USING (true) WITH CHECK (true);

-- 2. MENU ITEMS TABLE
CREATE TABLE IF NOT EXISTS public.menu_items (
    id TEXT PRIMARY KEY,
    place_id TEXT NOT NULL,
    name TEXT NOT NULL,
    description TEXT,
    price INT NOT NULL DEFAULT 15000,
    image_url TEXT,
    category TEXT NOT NULL DEFAULT 'Kopi',
    is_available BOOLEAN DEFAULT TRUE,
    stok INT DEFAULT 20,
    satuan_stok TEXT DEFAULT 'porsi',
    created_at TIMESTAMPTZ DEFAULT NOW()
);

ALTER TABLE public.menu_items ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Public menu select" ON public.menu_items;
CREATE POLICY "Public menu select" ON public.menu_items FOR SELECT TO PUBLIC USING (true);
DROP POLICY IF EXISTS "Public menu all" ON public.menu_items;
CREATE POLICY "Public menu all" ON public.menu_items FOR ALL TO PUBLIC USING (true) WITH CHECK (true);

-- 3. PROFILES TABLE
CREATE TABLE IF NOT EXISTS public.profiles (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    username TEXT,
    email TEXT,
    phone TEXT,
    role TEXT NOT NULL DEFAULT 'customer',
    store_id TEXT,
    store_name TEXT,
    avatar_url TEXT,
    status TEXT DEFAULT 'active',
    created_at TIMESTAMPTZ DEFAULT NOW()
);

ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Public profiles select" ON public.profiles;
CREATE POLICY "Public profiles select" ON public.profiles FOR SELECT TO PUBLIC USING (true);
DROP POLICY IF EXISTS "Public profiles all" ON public.profiles;
CREATE POLICY "Public profiles all" ON public.profiles FOR ALL TO PUBLIC USING (true) WITH CHECK (true);

-- 4. ORDERS TABLE
CREATE TABLE IF NOT EXISTS public.orders (
    id TEXT PRIMARY KEY,
    order_number TEXT NOT NULL,
    user_id TEXT NOT NULL,
    place_id TEXT NOT NULL,
    place_name TEXT NOT NULL,
    place_address TEXT,
    place_image_url TEXT,
    items JSONB DEFAULT '[]'::jsonb,
    subtotal INT NOT NULL DEFAULT 0,
    service_fee INT NOT NULL DEFAULT 2000,
    total INT NOT NULL DEFAULT 0,
    payment_method TEXT NOT NULL DEFAULT 'cash',
    payment_status TEXT NOT NULL DEFAULT 'unpaid',
    status TEXT NOT NULL DEFAULT 'processing',
    dining_option TEXT NOT NULL DEFAULT 'dine_in',
    table_number TEXT,
    notes TEXT,
    has_reviewed BOOLEAN DEFAULT FALSE,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Public orders all" ON public.orders;
CREATE POLICY "Public orders all" ON public.orders FOR ALL TO PUBLIC USING (true) WITH CHECK (true);

-- 5. REVIEWS TABLE
CREATE TABLE IF NOT EXISTS public.reviews (
    id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,
    place_id TEXT NOT NULL,
    user_id TEXT NOT NULL,
    user_name TEXT NOT NULL,
    user_avatar TEXT,
    order_id TEXT,
    rating NUMERIC(2,1) NOT NULL DEFAULT 5.0,
    comment TEXT NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

ALTER TABLE public.reviews ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Public reviews all" ON public.reviews;
CREATE POLICY "Public reviews all" ON public.reviews FOR ALL TO PUBLIC USING (true) WITH CHECK (true);

-- INDEXES FOR FAST QUERIES
CREATE INDEX IF NOT EXISTS idx_places_category ON public.places(category);
CREATE INDEX IF NOT EXISTS idx_places_rating ON public.places(rating DESC);
CREATE INDEX IF NOT EXISTS idx_menu_items_place_id ON public.menu_items(place_id);
CREATE INDEX IF NOT EXISTS idx_orders_user_id ON public.orders(user_id);
CREATE INDEX IF NOT EXISTS idx_reviews_place_id ON public.reviews(place_id);



-- =============================================================================
-- SEED DEMO USERS & PROFILES
-- =============================================================================
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, role = EXCLUDED.role, store_id = EXCLUDED.store_id;

